-- rental adjustments (reached through the parent rental, scoped to tenant 1)
INSERT INTO rental_adjustment (rental_pk, line_no, kind, amount_cents, affects_net, effective_date, hold_released, email_message_id, notes)
SELECT rental_pk, 1, 'hold', 30000, 0, '2026-09-05', 0, NULL, 'Refundable security deposit mentioned at booking; no release email found'
  FROM rental WHERE tenant_id = 1 AND company = 'Avis' AND confirmation_no = '25158422US2'
ON CONFLICT (rental_pk, line_no) DO NOTHING;
INSERT INTO rental_adjustment (rental_pk, line_no, kind, amount_cents, affects_net, effective_date, hold_released, email_message_id, notes)
SELECT rental_pk, 1, 'reimbursement', 1600, 0, '2026-09-25', NULL, NULL, 'BWI parking paid out of pocket, reimbursed by Turo (net zero; not part of gross)'
  FROM rental WHERE tenant_id = 1 AND company = 'Turo' AND confirmation_no = '61075405'
